from sys import stdin
for _ in range(int(stdin.readline())):
	(n, k) = map(int, stdin.readline().rstrip().split())
	arr = stdin.readline().rstrip()

	def countMag(arr, k):
		(iron, mag, sheets) = ([], [], [])
		(l, temp) = (len(arr), 0)
		for i in range(l):
			if arr[i] == 'I':
				iron += [i]
			elif arr[i] == 'M':
				mag += [i]
			elif arr[i] == ':':
				temp += 1
			sheets += [temp]
		cnt = i = j = 0
		while i < len(iron) and j < len(mag):
			if iron[i] > mag[j]:
				power = k + 1 - (iron[i] - mag[j]) - (sheets[iron[i]] - sheets[mag[j]])
			else:
				power = k + 1 - (mag[j] - iron[i]) - (sheets[mag[j]] - sheets[iron[i]])
			if power > 0:
				cnt += 1
				i += 1
				j += 1
			elif iron[i] > mag[j]:
				j += 1
			elif iron[i] < mag[j]:
				i += 1
		return cnt
	result = 0
	for ele in arr.split('X'):
		result += countMag(ele, k)
	print(result)
